:root {
  color-scheme: dark;
  --ink: #090b0a;
  --panel: #0d100e;
  --panel-raised: #111512;
  --line: #2b322d;
  --muted: #858c85;
  --paper: #e9eee8;
  --green: #20ef4f;
  --green-dim: #087d2a;
  --cyan: #91f3a8;
  --grid-line: rgba(32, 239, 79, .025);
  --orb-core: #010602;
  --orb-glow: #20ef4f;
  --mono: "DM Mono", "Courier New", monospace;
  --display: "Space Grotesk", "Trebuchet MS", sans-serif;
  font-family: var(--mono);
  background: var(--ink);
  color: var(--paper);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 32px; }
body {
  min-width: 320px;
  margin: 0;
  background-color: var(--ink);
  background-image: linear-gradient(var(--grid-line) 1px, transparent 1px), linear-gradient(90deg, var(--grid-line) 1px, transparent 1px);
  background-size: 48px 48px;
  color: var(--paper);
}
a { color: inherit; text-decoration: none; }
button, input { font: inherit; }
button:focus-visible, a:focus-visible, input:focus-visible { outline: 2px solid var(--green); outline-offset: 4px; }
.is-option-selected:focus-visible { outline: 0; }
.page-shell { width: min(1120px, calc(100% - 64px)); margin: 0 auto; }
.topbar { min-height: 76px; display: flex; align-items: center; gap: 30px; border-bottom: 1px solid var(--line); }
.wordmark { display: inline-flex; align-items: center; gap: 10px; color: var(--paper); font: 600 13px var(--mono); letter-spacing: 0; white-space: nowrap; }
.wordmark-mark { color: var(--green); font: 700 19px var(--display); }
.wordmark-mark span { color: var(--paper); }
.wordmark-muted { color: var(--muted); }
.system-status { display: flex; align-items: center; gap: 9px; color: var(--muted); font-size: 10px; }
.status-light { width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 12px rgba(157, 242, 173, .7); }
.site-nav { display: flex; gap: 25px; margin-left: auto; }
